// Helper: Alle Fotos für eine bestimmte Page holen
export function getPhotosForPage(page: string): Photo[] {
  return PHOTOS.filter((p) => p.suggestedPages.includes(page));
}

// Helper: Alle Fotos einer Kategorie holen
export function getPhotosByCategory(category: PhotoCategory): Photo[] {
  return PHOTOS.filter((p) => p.category === category);
}

// Helper: Zufälliges Foto einer Kategorie
export function getRandomPhotoByCategory(
  category: PhotoCategory,
): Photo | undefined {
  const filtered = getPhotosByCategory(category);
  if (filtered.length === 0) return undefined;
  return filtered[Math.floor(Math.random() * filtered.length)];
}

// Helper: Alle Fotos mit einem bestimmten Tag
export function getPhotosByTag(tag: string): Photo[] {
  return PHOTOS.filter((p) => p.tags.includes(tag));
}
